/*
 * src/os/errno_sparc.h — asm-generic errno numbers to the SPARC numbering
 *
 * Copyright 2026 Moritz Angermann <moritz@zw3rk.com>, zw3rk pte. ltd.
 * SPDX-License-Identifier: Apache-2.0
 *
 * arch/sparc/include/uapi/asm/errno.h renumbers most errnos from
 * ENOLCK/ENOSYS onward. The table below is generated by name from the
 * asm-generic and sparc64 UAPI headers; numbers that agree are absent
 * (identity). Used for host errnos that have no explicit case in
 * sparc64_host_errno_to_guest on a Linux host.
 */
#ifndef SPARC64RT_OS_ERRNO_SPARC_H
#define SPARC64RT_OS_ERRNO_SPARC_H

#include <stdint.h>

static inline uint64_t sparc64_errno_generic_to_sparc(long e)
{
    switch (e) {
    case 35:
        return 78u; /* EDEADLK */
    case 36:
        return 63u; /* ENAMETOOLONG */
    case 37:
        return 79u; /* ENOLCK */
    case 38:
        return 90u; /* ENOSYS */
    case 39:
        return 66u; /* ENOTEMPTY */
    case 40:
        return 62u; /* ELOOP */
    case 42:
        return 75u; /* ENOMSG */
    case 43:
        return 77u; /* EIDRM */
    case 44:
        return 94u; /* ECHRNG */
    case 45:
        return 95u; /* EL2NSYNC */
    case 46:
        return 96u; /* EL3HLT */
    case 47:
        return 97u; /* EL3RST */
    case 48:
        return 98u; /* ELNRNG */
    case 49:
        return 99u; /* EUNATCH */
    case 50:
        return 100u; /* ENOCSI */
    case 51:
        return 101u; /* EL2HLT */
    case 52:
        return 102u; /* EBADE */
    case 53:
        return 103u; /* EBADR */
    case 54:
        return 104u; /* EXFULL */
    case 55:
        return 105u; /* ENOANO */
    case 56:
        return 106u; /* EBADRQC */
    case 57:
        return 107u; /* EBADSLT */
    case 59:
        return 109u; /* EBFONT */
    case 60:
        return 72u; /* ENOSTR */
    case 61:
        return 111u; /* ENODATA */
    case 62:
        return 73u; /* ETIME */
    case 63:
        return 74u; /* ENOSR */
    case 64:
        return 80u; /* ENONET */
    case 65:
        return 113u; /* ENOPKG */
    case 66:
        return 71u; /* EREMOTE */
    case 67:
        return 82u; /* ENOLINK */
    case 68:
        return 83u; /* EADV */
    case 69:
        return 84u; /* ESRMNT */
    case 70:
        return 85u; /* ECOMM */
    case 71:
        return 86u; /* EPROTO */
    case 72:
        return 87u; /* EMULTIHOP */
    case 73:
        return 88u; /* EDOTDOT */
    case 74:
        return 76u; /* EBADMSG */
    case 75:
        return 92u; /* EOVERFLOW */
    case 76:
        return 115u; /* ENOTUNIQ */
    case 77:
        return 93u; /* EBADFD */
    case 78:
        return 89u; /* EREMCHG */
    case 79:
        return 114u; /* ELIBACC */
    case 80:
        return 112u; /* ELIBBAD */
    case 81:
        return 124u; /* ELIBSCN */
    case 82:
        return 123u; /* ELIBMAX */
    case 83:
        return 110u; /* ELIBEXEC */
    case 84:
        return 122u; /* EILSEQ */
    case 85:
        return 116u; /* ERESTART */
    case 86:
        return 91u; /* ESTRPIPE */
    case 87:
        return 68u; /* EUSERS */
    case 88:
        return 38u; /* ENOTSOCK */
    case 89:
        return 39u; /* EDESTADDRREQ */
    case 90:
        return 40u; /* EMSGSIZE */
    case 91:
        return 41u; /* EPROTOTYPE */
    case 92:
        return 42u; /* ENOPROTOOPT */
    case 93:
        return 43u; /* EPROTONOSUPPORT */
    case 94:
        return 44u; /* ESOCKTNOSUPPORT */
    case 95:
        return 45u; /* EOPNOTSUPP */
    case 96:
        return 46u; /* EPFNOSUPPORT */
    case 97:
        return 47u; /* EAFNOSUPPORT */
    case 98:
        return 48u; /* EADDRINUSE */
    case 99:
        return 49u; /* EADDRNOTAVAIL */
    case 100:
        return 50u; /* ENETDOWN */
    case 101:
        return 51u; /* ENETUNREACH */
    case 102:
        return 52u; /* ENETRESET */
    case 103:
        return 53u; /* ECONNABORTED */
    case 104:
        return 54u; /* ECONNRESET */
    case 105:
        return 55u; /* ENOBUFS */
    case 106:
        return 56u; /* EISCONN */
    case 107:
        return 57u; /* ENOTCONN */
    case 108:
        return 58u; /* ESHUTDOWN */
    case 109:
        return 59u; /* ETOOMANYREFS */
    case 110:
        return 60u; /* ETIMEDOUT */
    case 111:
        return 61u; /* ECONNREFUSED */
    case 112:
        return 64u; /* EHOSTDOWN */
    case 113:
        return 65u; /* EHOSTUNREACH */
    case 114:
        return 37u; /* EALREADY */
    case 115:
        return 36u; /* EINPROGRESS */
    case 116:
        return 70u; /* ESTALE */
    case 122:
        return 69u; /* EDQUOT */
    case 123:
        return 125u; /* ENOMEDIUM */
    case 124:
        return 126u; /* EMEDIUMTYPE */
    case 125:
        return 127u; /* ECANCELED */
    case 126:
        return 128u; /* ENOKEY */
    case 127:
        return 129u; /* EKEYEXPIRED */
    case 128:
        return 130u; /* EKEYREVOKED */
    case 129:
        return 131u; /* EKEYREJECTED */
    case 130:
        return 132u; /* EOWNERDEAD */
    case 131:
        return 133u; /* ENOTRECOVERABLE */
    case 132:
        return 134u; /* ERFKILL */
    case 133:
        return 135u; /* EHWPOISON */
    case 134:
        return 136u; /* EFTYPE */
    default:
        return (uint64_t)e;
    }
}

#endif /* SPARC64RT_OS_ERRNO_SPARC_H */
